mapper.select:
SELECT , COUNT(h.hold_id) AS active_hold_count, (SELECT MAX(h2.released_at) FROM stock_hold h2 WITH (NOLOCK) WHERE h2.lot_no = l.lot_no) AS last_released_at FROM stock_lot l WITH (NOLOCK) JOIN product p WITH (NOLOCK) ON p.product_code = l.product_code
LEFT JOIN stock_hold h WITH (NOLOCK) ON h.lot_no = l.lot_no AND h.released_at IS NULL WHERE l.status IN ('AVAILABLE', 'HOLD')
AND p.category = #{category}
AND p.product_code LIKE CONCAT(#{productCode}, '%')
AND l.expiry_date >= #{monthStart} AND l.expiry_date < #{nextMonthStart}
GROUP BY ORDER BY p.category, p.product_code, l.expiry_date, l.lot_no
